package android.content.pm;public class PackageManager{public static final String FEATURE_PICTURE_IN_PICTURE="android.software.picture_in_picture";public boolean pip=true;public boolean hasSystemFeature(String name){return pip;}public boolean installed=true;public int queries;public ApplicationInfo getApplicationInfo(String pkg,int flags)throws Exception{queries++;if(!installed)throw new Exception();return new ApplicationInfo();}public android.graphics.drawable.Drawable getApplicationIcon(String name)throws Exception{if(!installed)throw new Exception();return new android.graphics.drawable.Drawable();}}